                ("labelId", "type:string;format:uuid"),
                ("locationId", "type:null|string;format:uuid"),
                ("movementKind", "type:string"),
                ("productId", "type:string;format:uuid"),
                ("requestedKg", "type:string"),
                ("sourceId", "type:string;format:uuid"),
                ("sourceKind", "type:string"),
                ("sourceLineId", "type:null|string;format:uuid")),
            ["ProductRuntimeFieldError"] = ObjectSchema(["field", "code"],
                ("code", "type:string"),
                ("field", "type:string")),
            ["ProductRuntimeProblemContract"] = ObjectSchema(["type", "title", "status"],
                ("code", "type:null|string"),
                ("correlationId", "type:null|string"),
                ("currentVersion", "type:string"),
                ("detail", "type:null|string"),
                ("errors", "type:array|null;items:ref:ProductRuntimeFieldError"),
                ("expectedVersion", "type:string"),
                ("instance", "type:null|string"),
                ("status", "type:integer;format:int32"),
                ("title", "type:string"),
                ("type", "type:string")),
        };

    [Fact]
    public async Task BuildTimeContract_IsDeterministicSecretFreeAndDoesNotContactConfiguredDependencies()
    {
        var repositoryRoot = FindRepositoryRoot();
        var temporaryRoot = Path.Combine(
            Path.GetTempPath(),
            $"goymen-erp-openapi-{Guid.NewGuid():N}");
        Directory.CreateDirectory(temporaryRoot);

        try
        {
            var first = await GenerateAsync(
                repositoryRoot,
                temporaryRoot,
                "Production",
                "first");
            var second = await GenerateAsync(
                repositoryRoot,
                temporaryRoot,
                "Production",
                "second");
            var development = await GenerateAsync(
                repositoryRoot,
                temporaryRoot,
                "Development",
                "development");

            Assert.Equal(first.Bytes, second.Bytes);
            Assert.Equal(first.Bytes, development.Bytes);
            Assert.Equal(0, first.AcceptedConnectionCount);
            Assert.Equal(0, second.AcceptedConnectionCount);
            Assert.Equal(0, development.AcceptedConnectionCount);

            var canonicalArtifactPath = Path.Combine(
                repositoryRoot,
                "artifacts",
                CanonicalFileName);
            Assert.True(
                File.Exists(canonicalArtifactPath),
                $"MSBuild canonical artifact was not emitted at {canonicalArtifactPath}.");
            Assert.Equal(
                first.Bytes,
                await File.ReadAllBytesAsync(canonicalArtifactPath));

            var contractText = Encoding.UTF8.GetString(first.Bytes);
            using var contract = JsonDocument.Parse(first.Bytes);
            var contractSurfaces = ReadContractStrings(contract.RootElement).Append(contractText).ToArray();
            // A short OS username can be public contract text ("CI/AS", "official").
            // Unique configured secret markers cover credential values; full host
            // paths, including decoded JSON escapes, cover sensitive locations.
            var userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
            Assert.False(string.IsNullOrWhiteSpace(userProfile));
            foreach (var forbiddenValue in new[]
                     {
                         first.SecretMarker,
                         second.SecretMarker,
                         development.SecretMarker,
                         repositoryRoot,
                         repositoryRoot.Replace('\\', '/'),
                         temporaryRoot,
                         temporaryRoot.Replace('\\', '/'),
                         userProfile,
                         userProfile.Replace('\\', '/'),
                         Environment.MachineName,
                         "openapi.invalid",
                         "127.0.0.1",
                         "DB_CONNECTION_STRING",
                         "Password=",
                         "SELECT ",
                     })
            {
                foreach (var surface in contractSurfaces)
                {
                    Assert.DoesNotContain(forbiddenValue, surface, StringComparison.OrdinalIgnoreCase);
                }
            }

            AssertContractShape(first.Bytes);
        }
        finally
        {
            Directory.Delete(temporaryRoot, recursive: true);
        }
    }

    [Theory]
    [InlineData("{\"path\":\"C:\\\\Users\\\\private-user\"}", "C:\\Users\\private-user")]
    [InlineData("{\"metadata\":[{\"path\":\"\\u002fhome\\u002fprivate-user\"}]}", "/home/private-user")]
    [InlineData("{\"\\u0073ecret-key\":\"public\"}", "secret-key")]
    public void ContractPrivacySurfaces_DecodeEscapedHostPathsAndPropertyNames(string json, string marker)
    {
        using var contract = JsonDocument.Parse(json);
        Assert.Contains(marker, ReadContractStrings(contract.RootElement));
    }

    private static IEnumerable<string> ReadContractStrings(JsonElement element)
    {
        if (element.ValueKind == JsonValueKind.String)
        {
            yield return element.GetString()!;
        }
        else if (element.ValueKind == JsonValueKind.Object)
        {
            foreach (var property in element.EnumerateObject())
            {
                yield return property.Name;
                foreach (var value in ReadContractStrings(property.Value))
                {
                    yield return value;
                }
            }
        }
        else if (element.ValueKind == JsonValueKind.Array)
        {
            foreach (var item in element.EnumerateArray())
            {
                foreach (var value in ReadContractStrings(item))
                {
                    yield return value;
                }
            }
        }
    }

