        Assert.True(libraries.TryGetProperty(
            "Microsoft.Extensions.ApiDescription.Server/10.0.11",
            out _));

        var packageRoot = assets.RootElement.GetProperty("packageFolders")
            .EnumerateObject()
            .Select(property => property.Name)
